import {interpolate,celsius} from './calc.js';
import {KEY,addRecord,deleteRecord,restoreRecord,readRecords} from './history.js';
import {readSettings,historyLimit} from '../prefs.mjs';
let keep=historyLimit();
// Settings can choose the units new calculations start in; "default" keeps this calculator's own.
const preferred=list=>{const s=readSettings();const pick=label=>list.find(u=>u[1]===label)?.[0];return {pressure:pick(s.pressure),temperature:pick(s.temperature)};};
import {formatDate,formatDateTime,formatTime} from '../dates.mjs';
// The saved note names the day too when the calculation is not from today, and goes once its record is deleted.
const savedAt=date=>formatDate(date)===formatDate(Date.now())?formatTime(date):formatDateTime(date);
import {toast,confirmAction} from '../feedback.mjs';
const $=id=>document.getElementById(id);
const pressure=[['bara','bar(a)',1,0],['barg','bar(g)',1,1.01325],['kPa','kPa(a)',.01,0],['MPa','MPa(a)',10,0],['psia','psia',.06894757293168,0],['psig','psig',.06894757293168,1.01325],['kgfa','Kg/cm2(a)',.980665,0]],temperature=[['C','°C'],['F','°F'],['K','K']];
const units=[...pressure,...temperature],unitLabel=u=>units.find(d=>d[0]===u)?.[1]||u;
const fmt=n=>n.toLocaleString('en-US',{maximumFractionDigits:4}),fixed=n=>n.toLocaleString('en-US',{minimumFractionDigits:2,maximumFractionDigits:2});
const title=r=>r.mode==='pt'?'Saturation temperature':'Saturation pressure',inputTitle=r=>r.mode==='pt'?'Pressure':'Temperature';
// Shared and downloaded reports keep their own date format; everything on screen goes through dates.mjs.
const dateLabel=r=>new Date(r.date).toISOString();
const TRASH='<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.25" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M10 11v6"/><path d="M14 11v6"/><path d="M19 6v14a2 2 0 0 1-2 2H7a2 2 0 0 1-2-2V6"/><path d="M3 6h18"/><path d="M8 6V4a2 2 0 0 1 2-2h4a2 2 0 0 1 2 2v2"/></svg>';
const tempFromC=(n,u)=>u==='F'?n*9/5+32:u==='K'?n+273.15:n;
const options=(el,list)=>{el.replaceChildren(...list.map(([v,l])=>{const o=document.createElement('option');o.value=v;o.textContent=l;return o}))};
let records=[],current=null,selected=null,shareRecord=null,storageOK=true;
const usable=r=>(r.mode==='pt'?pressure:temperature).some(u=>u[0]===r.inputUnit)&&(r.mode==='pt'?temperature:pressure).some(u=>u[0]===r.outputUnit);
// History is re-read before every change: another tab or Settings may have changed or deleted it since.
function fresh(){try{records=readRecords(localStorage,keep).filter(usable)}catch{}}
try{records=readRecords(localStorage,keep).filter(usable)}catch{storageOK=false}
function noteText(){if(!current)return '';if(!storageOK)return 'Kept for this session only. This browser can\'t save history.';return records.some(r=>r.id===current.id)?`Saved to History at ${savedAt(current.date)}.`:'';}
function save(){try{localStorage.setItem(KEY,JSON.stringify(records));storageOK=true}catch{storageOK=false}renderHistory()}
function resultValue(r){if(r.mode==='pt')return tempFromC(r.t,r.outputUnit);const u=pressure.find(d=>d[0]===r.outputUnit);return (r.p-u[3])/u[2]}
const headline=r=>`${fixed(resultValue(r))} ${unitLabel(r.outputUnit)}`,facts=r=>[title(r),`${inputTitle(r).toLowerCase()} ${fmt(r.input)} ${unitLabel(r.inputUnit)}`].join(', ');
function report(r){return `Ammonia Saturation Condition\n${dateLabel(r)}\n\nInput — ${inputTitle(r)}: ${fmt(r.input)} ${unitLabel(r.inputUnit)}\nOutput — ${title(r)}: ${fixed(resultValue(r))} ${unitLabel(r.outputUnit)}\n\nTable interpolation\n${[r.inputUnit,r.outputUnit].some(u=>['barg','psig'].includes(u))?'Gauge reference: 1.01325 bar atmospheric pressure.\n':''}`}
function updateRange(){const pt=$('mode').value==='pt',unit=$('unit').value;let lo,hi,label;if(pt){const u=pressure.find(d=>d[0]===unit);lo=(.386-u[3])/u[2];hi=(113-u[3])/u[2];label=u[1]}else{lo=tempFromC(-51.1,unit);hi=tempFromC(132,unit);label=unitLabel(unit)}$('value').inputMode=lo<0?'text':'decimal';$('range').textContent=`Range: ${fmt(lo)} to ${fmt(hi)} ${label}`;$('gauge-note').hidden=![unit,$('output-unit').value].some(u=>u==='barg'||u==='psig')}
const resultParts=()=>[document.querySelector('#output-panel .result-row'),document.querySelector('#output-panel .result-actions'),$('saved-note')];
function clearError(){$('error').hidden=true;$('error').textContent='';$('value').removeAttribute('aria-invalid');$('value').setAttribute('aria-describedby','range')}
function showError(message){$('error').textContent=message;$('error').hidden=false;$('value').setAttribute('aria-invalid','true');$('value').setAttribute('aria-describedby','error range')}
function updateClear(){const empty=!$('value').value.trim();$('clear').disabled=empty&&!current;$('calculate').disabled=empty;$('calculate-hint').hidden=!empty}
function clearResult(){current=null;$('result-empty').hidden=false;resultParts().forEach(e=>e.hidden=true);$('saved-note').textContent='';$('workspace').classList.remove('has-result');clearError();$('status').textContent='';updateRange();updateClear()}
function setup(){const pt=$('mode').value==='pt';$('input-heading').textContent=pt?'Pressure':'Temperature';$('value').setAttribute('aria-label',pt?'Pressure value':'Temperature value');$('result-empty-text').textContent=pt?'Enter a pressure, then calculate. The saturation temperature appears here.':'Enter a temperature, then calculate. The saturation pressure appears here.';$('value').value='';options($('unit'),pt?pressure:temperature);options($('output-unit'),pt?temperature:pressure);{const p=preferred(pressure).pressure,t=preferred(temperature).temperature;if(pt){if(p)$('unit').value=p;if(t)$('output-unit').value=t}else{if(t)$('unit').value=t;if(p)$('output-unit').value=p}}clearResult()}
function renderResult(){if(!current)return;$('result-empty').hidden=true;resultParts().forEach(e=>e.hidden=false);updateClear();$('workspace').classList.add('has-result');$('result-heading').textContent=title(current);$('result').textContent=fixed(resultValue(current));$('saved-note').textContent=noteText();updateRange()}
function element(tag,text,cls){const e=document.createElement(tag);if(text!==undefined)e.textContent=text;if(cls)e.className=cls;return e}
function button(text,fn,cls='soft'){const b=element('button',text,cls);b.type='button';b.onclick=fn;return b}
// The history dialog is modal, so a message bar left in <body> would sit under it, inert: it moves to whichever layer is on top.
function notify(text,options){toast(text,options);const bar=$('toast'),dialog=$('history-dialog');if(bar)(dialog.open?dialog:document.body).append(bar)}
function trash(r){const b=button('',()=>remove(r.id),'action-icon'),label=`Delete calculation from ${formatDateTime(r.date)}`;b.setAttribute('aria-label',label);b.title=label;b.innerHTML=TRASH;return b}
function card(r){const row=element('div',undefined,'history-row'),b=button('',()=>showDetail(r.id),'history-card');b.append(element('strong',headline(r)),element('small',formatDateTime(r.date)),element('span',facts(r)));row.append(b,trash(r));return row}
function renderHistory(){if(current)$('saved-note').textContent=noteText();const n=records.length;$('delete-all').disabled=!n;$('history-meta').textContent=storageOK?`${n} saved on this device. The last ${keep} are kept.`:'Saved for this session only. This browser can\'t keep history.';$('history-list').replaceChildren(...records.map(r=>card(r)));if(!n)$('history-list').append(element('p','No saved calculations yet.','empty'))}
function revealHistory(){if(!$('history-dialog').open)$('history-dialog').showModal();}
function closeHistory(){$('history-dialog').close();}
function openHistory(){fresh();selected=null;$('history-detail').hidden=true;$('history-list').hidden=false;$('history-status').textContent='';renderHistory();revealHistory()}
function focusCard(index){const cards=$('history-list').querySelectorAll('.history-card');(cards[Math.min(Math.max(index,0),cards.length-1)]||$('history-close')).focus()}
function remove(id){fresh();const index=records.findIndex(r=>r.id===id);if(index<0)return;const record=records[index];records=deleteRecord(records,id);save();if(selected===id)openHistory();if($('history-dialog').open&&!$('history-list').hidden)focusCard(index);notify('Calculation deleted',{action:'Undo',onAction:()=>{fresh();records=restoreRecord(records,record,index,keep);save();if($('history-dialog').open&&!$('history-list').hidden)focusCard(index)}})}
function showDetail(id){const r=records.find(r=>r.id===id);if(!r)return;selected=id;revealHistory();$('history-list').hidden=true;$('history-detail').hidden=false;const detail=$('history-detail');detail.replaceChildren();const actions=element('div',undefined,'history-detail-actions'),back=button('Back to History',()=>{openHistory();focusCard(records.findIndex(x=>x.id===id))},'secondary');actions.append(trash(r),back,button('Load Calculation',()=>load(r),'primary'));detail.append(actions,element('h3',title(r)),element('p',formatDateTime(r.date),'hint'));for(const [label,value] of [[inputTitle(r),`${fmt(r.input)} ${unitLabel(r.inputUnit)}`],[title(r),`${fixed(resultValue(r))} ${unitLabel(r.outputUnit)}`]]){const row=element('div',undefined,'detail-row');row.append(element('span',label),element('strong',value));detail.append(row)}const exports=document.querySelector('#output-panel .result-actions').cloneNode(true);exports.hidden=false;exports.querySelectorAll('[id]').forEach(node=>node.removeAttribute('id'));exports.querySelector(':scope>button').onclick=()=>openShare(r);const menu=exports.querySelector('details');menu.open=false;menu.querySelectorAll('div>button').forEach((node,index)=>node.onclick=()=>download(r,index===0?'csv':'txt'));detail.append(exports);$('history-status').textContent='';back.focus()}
function load(r){$('mode').value=r.mode;setup();$('value').value=r.input;$('unit').value=r.inputUnit;$('output-unit').value=r.outputUnit;current={...r};renderResult();closeHistory();notify('Saved calculation loaded');window.dispatchEvent(new CustomEvent('fieldkit:result'))}
function openShare(r){shareRecord={...r};$('share-text').value=report(r);$('share-status').textContent='';$('native-share').hidden=typeof navigator.share!=='function';$('share-dialog').showModal()}
function download(r,type){const quote=v=>'"'+String(v).replaceAll('"','""')+'"';const body=type==='txt'?report(r):[['Date (ISO)','Input property','Input value','Input unit','Output property','Output value','Output unit'],[r.date,inputTitle(r),r.input,unitLabel(r.inputUnit),title(r),resultValue(r),unitLabel(r.outputUnit)]].map(row=>row.map(quote).join(',')).join('\r\n');const blob=new Blob([type==='csv'?'\uFEFF':'',body],{type:type==='csv'?'text/csv;charset=utf-8':'text/plain;charset=utf-8'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=`ammonia-${r.mode}-${r.date.replace(/[:.]/g,'-')}.${type}`;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);($('history-dialog').open?$('history-status'):$('status')).textContent='Download prepared.';document.querySelectorAll('details[open]').forEach(d=>d.open=false)}
$('mode').onchange=setup;$('unit').onchange=clearResult;$('value').oninput=clearResult;$('clear').onclick=()=>{setup();$('value').focus()};
$('example').onclick=async()=>{if($('value').value.trim()&&!(await confirmAction({title:'Replace Your Readings?',message:'Load Example replaces the readings you have entered.',confirmLabel:'Replace'})))return;const pt=$('mode').value==='pt';$('unit').value=pt?'bara':'C';clearResult();$('value').value=pt?'5':'20';updateClear();$('value').focus()};
$('output-unit').onchange=()=>{if(!current)return;current.outputUnit=$('output-unit').value;fresh();records=records.map(r=>r.id===current.id?{...current}:r);save();renderResult()};
$('form').onsubmit=e=>{e.preventDefault();clearResult();try{if(!$('value').value.trim())throw Error('Enter a value to calculate.');if(!/^[+-]?(?:\d+\.?\d*|\.\d+)(?:[eE][+-]?\d+)?$/.test($('value').value.trim()))throw Error('Enter a valid number.');const input=Number($('value').value),mode=$('mode').value,inputUnit=$('unit').value;let value=input;if(mode==='pt'){const u=pressure.find(d=>d[0]===inputUnit);value=value*u[2]+u[3]}else value=celsius(value,inputUnit);const p=interpolate(value,mode==='pt'?'p':'t');current={id:crypto.randomUUID(),date:new Date().toISOString(),mode,input,inputUnit,outputUnit:$('output-unit').value,t:p.t,p:p.p};fresh();records=addRecord(records,{...current},keep);save();renderResult();window.dispatchEvent(new CustomEvent('fieldkit:result'))}catch(e){showError(e.message);$('value').focus()}};
$('history-open').onclick=openHistory;$('history-close').onclick=()=>closeHistory();$('history-dialog').addEventListener('close',()=>{const bar=$('toast');if(bar?.parentNode===$('history-dialog'))document.body.append(bar)});$('delete-all').onclick=async()=>{const n=records.length;if(!n)return;if(!(await confirmAction({title:'Delete All Saved Calculations?',message:`This removes all ${n} saved ammonia calculations from this device. This can't be undone.`,confirmLabel:'Delete All'})))return;records=[];save();openHistory();$('history-status').textContent='All saved calculations deleted.';$('history-close').focus()};
$('share').onclick=()=>current&&openShare(current);$('share-close').onclick=()=>$('share-dialog').close();$('copy-share').onclick=async()=>{try{await navigator.clipboard.writeText($('share-text').value);$('share-status').textContent='Results copied. Paste them into your message.'}catch{$('share-text').focus();$('share-text').select();$('share-status').textContent='Select and copy the summary above.'}};
$('native-share').onclick=async()=>{try{await navigator.share({title:'Ammonia Saturation Condition result',text:report(shareRecord)});$('share-status').textContent='Share completed.'}catch(e){$('share-status').textContent=e.name==='AbortError'?'Sharing cancelled.':'Sharing is unavailable. Use Copy Results.'}};
$('download-csv').onclick=()=>current&&download(current,'csv');$('download-txt').onclick=()=>current&&download(current,'txt');
setup();renderHistory();

// Home links a saved calculation as ?open=<id>: show it in History, where Load Calculation is.
{const openId=new URLSearchParams(location.search).get('open');if(openId&&records.some(r=>r.id===openId)){showDetail(openId);window.history.replaceState(null,'',location.pathname);}}

// Changes from another tab or Settings: refresh the list and the saved note.
addEventListener('storage',e=>{if(e.key!==KEY&&e.key!==null)return;fresh();if(current)$('saved-note').textContent=noteText();if($('history-dialog').open){if(selected&&!records.some(r=>r.id===selected))openHistory();else if(!selected)renderHistory();}else renderHistory();});
addEventListener('storage',e=>{if(e.key!=='processcalc-settings-v1'&&e.key!==null)return;keep=historyLimit();renderHistory();});
